import{_ as o,o as r,c as e,a2 as n}from"./chunks/framework.DGzjq_gw.js";const c=JSON.parse('{"title":"按岗位差异化准备","description":"","frontmatter":{},"headers":[],"relativePath":"interview/per-jd-prep.md","filePath":"interview/per-jd-prep.md","lastUpdated":1792470007000}'),a={name:"interview/per-jd-prep.md"};function s(d,t,i,l,g,u){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="按岗位差异化准备" tabindex="-1">按岗位差异化准备 <a class="header-anchor" href="#按岗位差异化准备" aria-label="Permalink to &quot;按岗位差异化准备&quot;">​</a></h1><p>本页把 10 份深圳前端 JD（#1-#10）逐一拆成&quot;岗位画像 + 面试官重点问什么 + 短板应对话术 + 投递前必补清单 + 一句打招呼语&quot;，用于<strong>投递前的定向补强</strong>。编号、投递排序与补强清单均与 <a href="/frontend-kb-pages/guide/jd-overview">能力地图</a>、<a href="/frontend-kb-pages/guide/roadmap">备战路线</a> 保持一致。</p><blockquote><p>使用方式：投递某个岗位前，只读该岗位一节；&quot;必补清单&quot;里的链接是<strong>站在面试官视角的最短板</strong>，务必点开预习。</p></blockquote><h2 id="一、快速索引" tabindex="-1">一、快速索引 <a class="header-anchor" href="#一、快速索引" aria-label="Permalink to &quot;一、快速索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>梯队</th><th>岗位</th><th>一句话定位</th></tr></thead><tbody><tr><td>第一梯队</td><td>#9 今天国际</td><td>AI 协作 + 组件库 + 前端架构</td></tr><tr><td>第一梯队</td><td>#7 润信智能</td><td>智慧能源 + 数据大屏 + 数字孪生</td></tr><tr><td>第一梯队</td><td>#8 鹏开信息</td><td>IM + Electron + 音视频 + Hybrid</td></tr><tr><td>第一梯队</td><td>#2 四方精创</td><td>算力调度 + 数据标注 + 中后台</td></tr><tr><td>第二梯队</td><td>#1 星河视控</td><td>React 管理后台 + 监控/IoT + SDK 交付</td></tr><tr><td>第二梯队</td><td>#4 中科创达</td><td>前端全栈 + IoT 操作系统</td></tr><tr><td>第二梯队</td><td>#10 欣农互联</td><td>AI 产品（问答/Agent/RAG）+ RN 跨端</td></tr><tr><td>第二梯队</td><td>#6 鹏业软件</td><td>多端混合开发 + 信创</td></tr><tr><td>保底</td><td>#5 掌上智珠</td><td>标准中小团队前端（Vue 优先）</td></tr><tr><td>谨慎</td><td>#3 腾讯外包</td><td>可观测平台 + 监控 SDK + AI Agent</td></tr></tbody></table><h2 id="二、第一梯队-优先投递" tabindex="-1">二、第一梯队（优先投递） <a class="header-anchor" href="#二、第一梯队-优先投递" aria-label="Permalink to &quot;二、第一梯队（优先投递）&quot;">​</a></h2><h3 id="_9-今天国际-·-ai-协作-组件库-前端架构-匹配度约-96" tabindex="-1">#9 今天国际 · AI 协作 + 组件库 + 前端架构（匹配度约 96%） <a class="header-anchor" href="#_9-今天国际-·-ai-协作-组件库-前端架构-匹配度约-96" aria-label="Permalink to &quot;#9 今天国际 · AI 协作 + 组件库 + 前端架构（匹配度约 96%）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：已上市公司，500-999 人；要 AI 协作能力 + 组件库 + 前端架构，<strong>AI 协作是硬性第 2 条</strong>。</li><li><strong>面试官重点问</strong>：AI 辅助研发流程、组件库设计、跨域表述、架构分层与质量门禁。</li><li><strong>最大短板与话术</strong>：组件库有实战，但&quot;架构方法论&quot;易讲虚。话术：&quot;我把架构落到<strong>可执行的约束</strong>上——用 ESLint 规则守住依赖方向、用质量门禁卡住 AI 产出，而不是只谈分层名词。&quot;</li><li><strong>投递前必补</strong>：<a href="/frontend-kb-pages/ai/ai-assisted-dev">AI 辅助研发方法论</a> + <a href="/frontend-kb-pages/network/cross-origin">跨域速查</a>。</li><li><strong>打招呼语</strong>：&quot;我做过双栈同构组件库并对外交付，也用 AI 工具链 + 质量门禁做研发提效，正好契合贵司对 AI 协作与前端架构的要求。&quot;</li></ul><h3 id="_7-润信智能-·-智慧能源-数据大屏-数字孪生-匹配度约-92-·-16-20k·14薪" tabindex="-1">#7 润信智能 · 智慧能源 + 数据大屏 + 数字孪生（匹配度约 92% · 16-20K·14薪） <a class="header-anchor" href="#_7-润信智能-·-智慧能源-数据大屏-数字孪生-匹配度约-92-·-16-20k·14薪" aria-label="Permalink to &quot;#7 润信智能 · 智慧能源 + 数据大屏 + 数字孪生（匹配度约 92% · 16-20K·14薪）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：100-499 人未融资；智慧能源方向，数据大屏 + 数字孪生。</li><li><strong>面试官重点问</strong>：大屏适配方案、大数据量渲染性能、ECharts/DataV/Cesium 概念、WebGL/三维基础。</li><li><strong>最大短板与话术</strong>：数字孪生/三维是短板。话术：&quot;三维我项目里深度用得不深，但我知道数字孪生是<strong>三维场景 + 实时数据驱动的映射</strong>，底层是 WebGL/Cesium；渲染侧的性能思路（降采样、按需渲染、实例化）我在大屏里用过。&quot;</li><li><strong>投递前必补</strong>：<a href="/frontend-kb-pages/visualization/map-3d">DataV 组件列表</a> + <a href="/frontend-kb-pages/visualization/map-3d">Cesium 入门</a> + <a href="/frontend-kb-pages/performance/big-screen">大屏适配</a>。</li><li><strong>打招呼语</strong>：&quot;我做过数据大屏与大数据量渲染优化，也系统了解过 DataV/Cesium 与数字孪生的实现路径。&quot;</li></ul><h3 id="_8-鹏开信息-·-im-electron-音视频-hybrid-匹配度约-93" tabindex="-1">#8 鹏开信息 · IM + Electron + 音视频 + Hybrid（匹配度约 93%） <a class="header-anchor" href="#_8-鹏开信息-·-im-electron-音视频-hybrid-匹配度约-93" aria-label="Permalink to &quot;#8 鹏开信息 · IM + Electron + 音视频 + Hybrid（匹配度约 93%）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：500-999 人；IM + Electron 桌面端 + 音视频 + Hybrid。</li><li><strong>面试官重点问</strong>：IM 消息流与离线补偿、Electron IPC 与打包发布、WebRTC 概念、Hybrid/JSBridge 联调。</li><li><strong>最大短板与话术</strong>：IM 是 P0 缺口、企微是 D 级盲区。话术：&quot;IM 的<strong>消息不重不漏</strong>我很清楚——单调序号 + 客户端幂等去重 + 重连补偿拉取；企微 JS-SDK 我了解<strong>免登三跳</strong>的流程，细节会快速对齐。&quot;</li><li><strong>投递前必补</strong>：<a href="/frontend-kb-pages/network/im">IM 技术链</a> + <a href="#五、d-级单岗特化概念预习">企微概念</a> + <a href="/frontend-kb-pages/cross-platform/electron">Electron 深度</a>。</li><li><strong>打招呼语</strong>：&quot;我做过 Electron 桌面端与 Hybrid 联调，也理解 IM 的离线消息补偿与 WebRTC 音视频链路。&quot;</li></ul><h3 id="_2-四方精创-·-算力调度-数据标注-中后台-匹配度约-88" tabindex="-1">#2 四方精创 · 算力调度 + 数据标注 + 中后台（匹配度约 88%） <a class="header-anchor" href="#_2-四方精创-·-算力调度-数据标注-中后台-匹配度约-88" aria-label="Permalink to &quot;#2 四方精创 · 算力调度 + 数据标注 + 中后台（匹配度约 88%）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：1000-9999 人已上市；算力调度 + 数据标注 + 门户 + 中后台。</li><li><strong>面试官重点问</strong>：中后台复杂表单/表格、抗量级渲染、AntV 图表、Node.js/BFF、部署概念。</li><li><strong>最大短板与话术</strong>：AntV 生态与 Docker/K8s 是短板。话术：&quot;AntV 的 G2/G6/X6 我了解定位——分别是统计图表、图编辑、流程图；容器化我理解 CI 构建镜像 → 部署到 K8s 的基本链路。&quot;</li><li><strong>投递前必补</strong>：<a href="/frontend-kb-pages/visualization/antv">AntV</a> + <a href="/frontend-kb-pages/engineering/ci-cd">Docker/K8s 概念</a>。</li><li><strong>打招呼语</strong>：&quot;我熟悉 B 端中后台的复杂表单/表格与权限体系，也掌握 AntV 图表与前端工程化部署。&quot;</li></ul><h2 id="三、第二梯队-补-1-2-项技术后投递" tabindex="-1">三、第二梯队（补 1-2 项技术后投递） <a class="header-anchor" href="#三、第二梯队-补-1-2-项技术后投递" aria-label="Permalink to &quot;三、第二梯队（补 1-2 项技术后投递）&quot;">​</a></h2><h3 id="_1-星河视控-·-react-管理后台-监控-iot-sdk-交付-匹配度约-90" tabindex="-1">#1 星河视控 · React 管理后台 + 监控/IoT + SDK 交付（匹配度约 90%） <a class="header-anchor" href="#_1-星河视控-·-react-管理后台-监控-iot-sdk-交付-匹配度约-90" aria-label="Permalink to &quot;#1 星河视控 · React 管理后台 + 监控/IoT + SDK 交付（匹配度约 90%）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：0-20 人智能硬件；React 管理后台 + 监控/IoT + SDK 交付，团队小、要求全栈感强。</li><li><strong>面试官重点问</strong>：React 管理后台经验、实时数据（WebSocket）、WebRTC/音视频架构、SDK 交付。</li><li><strong>最大短板与话术</strong>：WebRTC 是 P1 缺口。话术：&quot;WebRTC 我理解核心链路——<code>getUserMedia</code> 采集 → <code>RTCPeerConnection</code> 建连（信令交换 SDP/ICE）→ 媒体流传输；架构上会用 SFU/MCU 做多人。&quot;</li><li><strong>投递前必补</strong>：<a href="/frontend-kb-pages/network/webrtc">WebRTC</a> + <a href="/frontend-kb-pages/network/webrtc">音视频架构</a>。</li><li><strong>打招呼语</strong>：&quot;我有 React 管理后台 + IoT 跨端 + SDK 交付经验，也了解 WebRTC 音视频与实时监控链路。&quot;</li></ul><h3 id="_4-中科创达-·-前端全栈-iot-操作系统-匹配度约-80-·-12-20k" tabindex="-1">#4 中科创达 · 前端全栈 + IoT 操作系统（匹配度约 80% · 12-20K） <a class="header-anchor" href="#_4-中科创达-·-前端全栈-iot-操作系统-匹配度约-80-·-12-20k" aria-label="Permalink to &quot;#4 中科创达 · 前端全栈 + IoT 操作系统（匹配度约 80% · 12-20K）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：10000+ 人已上市；前端全栈 + IoT 操作系统。</li><li><strong>面试官重点问</strong>：Node.js/服务端、接口设计与 BFF、IoT 设备侧交互、跨端。</li><li><strong>最大短板与话术</strong>：Node.js 深度是 P2 缺口。话术：&quot;我主力在前端，Node 侧做过 BFF 聚合接口与脚本工具；给我一周能把 Nest.js 最小 CRUD 落地。&quot;</li><li><strong>投递前必补</strong>：<a href="/frontend-kb-pages/backend/nestjs">Nest.js 最小 CRUD Demo</a> + <a href="/frontend-kb-pages/backend/nodejs">Node.js</a>。</li><li><strong>打招呼语</strong>：&quot;我前端全栈能力较均衡，熟悉 IoT 跨端交互，也能用 Node 做 BFF 与工具脚本。&quot;</li></ul><h3 id="_10-欣农互联-·-ai-产品-问答-agent-rag-rn-跨端-匹配度约-78-·-18-25k" tabindex="-1">#10 欣农互联 · AI 产品（问答/Agent/RAG）+ RN 跨端（匹配度约 78% · 18-25K） <a class="header-anchor" href="#_10-欣农互联-·-ai-产品-问答-agent-rag-rn-跨端-匹配度约-78-·-18-25k" aria-label="Permalink to &quot;#10 欣农互联 · AI 产品（问答/Agent/RAG）+ RN 跨端（匹配度约 78% · 18-25K）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：100-499 人未融资；AI 产品 + React Native 跨端，薪资高。</li><li><strong>面试官重点问</strong>：AI 产品界面（流式/Agent/RAG）、SSE/流式渲染、React Native 独立交付、跨端性能。</li><li><strong>最大短板与话术</strong>：RN 深度是短板。话术：&quot;RN 我理解是<strong>用 React 写原生</strong>，与 Web 的差异在布局（Flex 默认）、样式（无级联）、原生模块桥接；性能瓶颈靠 <code>FlatList</code> 虚拟化与 <code>InteractionManager</code>。&quot;</li><li><strong>投递前必补</strong>：<a href="/frontend-kb-pages/ai/streaming-ui">流式渲染</a> + <a href="/frontend-kb-pages/cross-platform/react-native">React Native</a>。</li><li><strong>打招呼语</strong>：&quot;我做过 AI 产品界面与流式渲染，也了解 RN 跨端与原生桥接，能快速承接 AI 产品前端。&quot;</li></ul><h3 id="_6-鹏业软件-·-多端混合开发-pc-android-ios-信创-匹配度约-86-·-11-21k" tabindex="-1">#6 鹏业软件 · 多端混合开发（PC/Android/iOS）+ 信创（匹配度约 86% · 11-21K） <a class="header-anchor" href="#_6-鹏业软件-·-多端混合开发-pc-android-ios-信创-匹配度约-86-·-11-21k" aria-label="Permalink to &quot;#6 鹏业软件 · 多端混合开发（PC/Android/iOS）+ 信创（匹配度约 86% · 11-21K）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：100-499 人；多端混合开发 + 信创国产化。</li><li><strong>面试官重点问</strong>：Hybrid/JSBridge、多端打包、浏览器/多端兼容、信创环境适配、公众号网页。</li><li><strong>最大短板与话术</strong>：信创与公众号是 D 级盲区。话术：&quot;信创环境的差异主要在<strong>内核与浏览器版本</strong>（如国产 OS + 特定浏览器），我会用特性检测 + polyfill + 降级方案兼顾；公众号授权我了解网页授权的基本流程。&quot;</li><li><strong>投递前必补</strong>：<a href="#五、d-级单岗特化概念预习">公众号/信创概念</a> + <a href="/frontend-kb-pages/cross-platform/react-native">多端打包</a>。</li><li><strong>打招呼语</strong>：&quot;我做过 Hybrid 与多端打包，也了解信创环境与公众号网页授权的适配要点。&quot;</li></ul><h2 id="四、保底与谨慎" tabindex="-1">四、保底与谨慎 <a class="header-anchor" href="#四、保底与谨慎" aria-label="Permalink to &quot;四、保底与谨慎&quot;">​</a></h2><h3 id="_5-掌上智珠-·-标准中小团队前端-vue-优先-匹配度约-95-·-10-15k" tabindex="-1">#5 掌上智珠 · 标准中小团队前端（Vue 优先）（匹配度约 95% · 10-15K） <a class="header-anchor" href="#_5-掌上智珠-·-标准中小团队前端-vue-优先-匹配度约-95-·-10-15k" aria-label="Permalink to &quot;#5 掌上智珠 · 标准中小团队前端（Vue 优先）（匹配度约 95% · 10-15K）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：20-99 人未融资；标准中小团队，Vue 优先，无短板但薪资偏低。</li><li><strong>面试官重点问</strong>：Vue 熟练度、业务落地速度、组件化、沟通协作。</li><li><strong>最大短板与话术</strong>：无技术硬短板。注意<strong>淡化炫技</strong>，多讲&quot;能快速稳定交付业务&quot;。话术：&quot;我 Vue 很熟，也做 React，落到具体业务我更关注<strong>交付质量与协作顺畅</strong>，不追求过度设计。&quot;</li><li><strong>投递前必补</strong>：无需额外补强，按 <a href="/frontend-kb-pages/framework/vue">Vue 3 深入</a> 复习即可。</li><li><strong>打招呼语</strong>：&quot;我 Vue/React 双栈熟练，能快速稳定落地业务，也有组件化与工程规范经验。&quot;</li></ul><h3 id="_3-腾讯外包-·-可观测平台-监控-sdk-ai-agent-匹配度约-83-·-10-13k" tabindex="-1">#3 腾讯外包 · 可观测平台 + 监控 SDK + AI Agent（匹配度约 83% · 10-13K） <a class="header-anchor" href="#_3-腾讯外包-·-可观测平台-监控-sdk-ai-agent-匹配度约-83-·-10-13k" aria-label="Permalink to &quot;#3 腾讯外包 · 可观测平台 + 监控 SDK + AI Agent（匹配度约 83% · 10-13K）&quot;">​</a></h3><ul><li><strong>岗位画像</strong>：10000+ 已上市；外包身份，可观测平台 + 监控 SDK + AI Agent，薪资带宽 10-13K。</li><li><strong>面试官重点问</strong>：监控 SDK/可观测体系、性能采集、AI Agent 界面、SDK 交付。</li><li><strong>最大短板与话术</strong>：监控 SDK 是 P0 缺口。话术：&quot;监控 SDK 关键有三点——<strong>可靠上报</strong>（sendBeacon）、<strong>异常隔离</strong>（不拖垮宿主）、<strong>可插拔插件</strong>（异常/性能/埋点分模块）。&quot;</li><li><strong>投递前必补</strong>：<a href="/frontend-kb-pages/performance/loading">监控三件套</a> + <a href="/frontend-kb-pages/network/webrtc">WebRTC</a>。</li><li><strong>打招呼语</strong>：&quot;我做过 SDK 交付与性能采集，理解可观测体系与监控 SDK 的可靠上报与异常隔离。&quot;</li><li><strong>注意</strong>：外包身份与薪资带宽需权衡，建议在 HR 面确认<strong>转正/归属/成长</strong>后再定。</li></ul><h2 id="五、d-级单岗特化概念预习" tabindex="-1">五、D 级单岗特化概念预习 <a class="header-anchor" href="#五、d-级单岗特化概念预习" aria-label="Permalink to &quot;五、D 级单岗特化概念预习&quot;">​</a></h2><blockquote><p>以下均为<strong>1 份 JD</strong> 的加分项，属&quot;面试前临时预习&quot;，会<strong>讲清核心概念</strong>即可，不要求项目经验。</p></blockquote><table tabindex="0"><thead><tr><th>概念</th><th>是什么</th><th>一句话讲清</th></tr></thead><tbody><tr><td><strong>企微 JS-SDK 免登三跳</strong></td><td>企业微信免登流程</td><td>三跳 = ①跳转企微授权页拿 <code>code</code> → ②用 <code>code</code> 换 <code>access_token</code>/用户身份 → ③带上身份进入业务页并免登（服务端配合）</td></tr><tr><td><strong>公众号网页授权</strong></td><td>微信网页授权</td><td><code>snsapi_base</code>（静默拿 openid）与 <code>snsapi_userinfo</code>（弹窗拿用户信息）两种 scope；流程：跳授权页 → 回调带 <code>code</code> → 换 <code>access_token</code> 与用户信息</td></tr><tr><td><strong>信创兼容</strong></td><td>国产化环境适配</td><td>国产 OS + 特定浏览器内核，差异在<strong>内核版本/特性支持</strong>；用特性检测 + polyfill + 降级，避免依赖新语法</td></tr><tr><td><strong>AntV</strong></td><td>蚂蚁可视化体系</td><td>G2（统计图表）、G6（图关系/图编辑）、X6（流程图/图编辑）、L7（地理空间）</td></tr><tr><td><strong>Docker / K8s</strong></td><td>容器化与编排</td><td>Docker 把应用打包成镜像；K8s 编排容器（Pod/Service/Deployment），前端关注&quot;构建镜像 → 部署&quot;链路</td></tr><tr><td><strong>WebRTC</strong></td><td>实时音视频</td><td>采集（<code>getUserMedia</code>）+ 建连（<code>RTCPeerConnection</code> + 信令 SDP/ICE）+ 传输；多人用 SFU/MCU 架构</td></tr><tr><td><strong>监控 SDK</strong></td><td>可观测采集端</td><td>采集（异常/性能/埋点）+ 可靠上报（<code>sendBeacon</code>）+ 异常隔离 + 采样 + sourcemap 还原</td></tr></tbody></table><p><strong>预习策略</strong>：每个概念记&quot;定义 + 一个关键机制 + 一个应用场景&quot;三句话即可；被深挖时用 <a href="/frontend-kb-pages/interview/">面试总览</a> 的&quot;讲不清&quot;补救话术过渡。</p><h2 id="六、投递顺序与演练节奏" tabindex="-1">六、投递顺序与演练节奏 <a class="header-anchor" href="#六、投递顺序与演练节奏" aria-label="Permalink to &quot;六、投递顺序与演练节奏&quot;">​</a></h2><p>按 <a href="/frontend-kb-pages/guide/roadmap">备战路线</a> 的三梯队推进，<strong>先练手找手感、再冲刺最想去的岗位</strong>：</p><table tabindex="0"><thead><tr><th>阶段</th><th>目标岗</th><th>演练重点</th></tr></thead><tbody><tr><td><strong>练手</strong></td><td>#5 掌上智珠</td><td>打磨自我介绍、答题节奏、项目叙述的&quot;问题-方案-权衡-结果&quot;四段式</td></tr><tr><td><strong>找手感</strong></td><td>#1 / #4 / #10 / #6</td><td>暴露短板、验证&quot;必补清单&quot;里的概念能否讲顺</td></tr><tr><td><strong>冲刺</strong></td><td>#9 / #7 / #8 / #2</td><td>用最好状态投递最想去的岗位，匹配度与回报综合最优</td></tr><tr><td><strong>权衡</strong></td><td>#3 腾讯外包</td><td>若考虑，先在 HR 面确认归属/成长/转正，再决定是否投</td></tr></tbody></table><h3 id="面试前-30-分钟热身清单" tabindex="-1">面试前 30 分钟热身清单 <a class="header-anchor" href="#面试前-30-分钟热身清单" aria-label="Permalink to &quot;面试前 30 分钟热身清单&quot;">​</a></h3><ol><li>复述一遍统一叙事主线：<strong>双栈同构组件库 + IoT 跨端 + AI 工具链质量门禁</strong>。</li><li>默背 3-5 个<strong>量化</strong>项目战绩（首屏耗时、包体大小、缺陷率、复用率）。</li><li>复习该岗&quot;必补清单&quot;里的 1-2 个概念，各准备&quot;三句话&quot;讲法。</li><li>想好 2 个反问问题（优先问业务目标与技术演进）。</li><li>过一遍&quot;讲不清&quot;补救话术，避免遇到盲区后心态崩盘。</li><li>确认岗位编号与方向画像，把打招呼语的第一句对准该岗最强标签。</li></ol><h3 id="三遍法结合使用" tabindex="-1">三遍法结合使用 <a class="header-anchor" href="#三遍法结合使用" aria-label="Permalink to &quot;三遍法结合使用&quot;">​</a></h3><ol><li><strong>第一遍 · 全局</strong>：通读 <a href="/frontend-kb-pages/interview/">面试总览</a> 建立答题方法论与叙事主线。</li><li><strong>第二遍 · 补弱</strong>：对照各页题库只攻薄弱项，重点补 <a href="/frontend-kb-pages/interview/js-questions">js-questions</a> 与 <a href="/frontend-kb-pages/interview/browser-network-questions">browser-network-questions</a>。</li><li><strong>第三遍 · 表达</strong>：按本页逐岗演练，把知识打磨成&quot;被问到能讲 3 分钟&quot;的口语化表达。</li></ol><h2 id="面试要点" tabindex="-1">面试要点 <a class="header-anchor" href="#面试要点" aria-label="Permalink to &quot;面试要点&quot;">​</a></h2><ol><li><strong>第一梯队怎么准备？</strong> 按 #9 → #7 → #8 → #2 顺序，各自点开&quot;必补清单&quot;定向预习，优先投递。</li><li><strong>第二梯队补什么？</strong> #1 补 WebRTC、#4 补 Node/Nest、#10 补 RN/流式、#6 补信创/公众号，各补 1-2 项即可投。</li><li><strong>保底与谨慎？</strong> #5 无硬短板、淡炫技重交付；#3 外包需在 HR 面确认归属与成长。</li><li><strong>D 级盲区怎么答？</strong> 记&quot;定义 + 关键机制 + 应用场景&quot;三句话，能讲清概念即可，深挖时用补救话术过渡。</li><li><strong>打招呼语的作用？</strong> 一句话命中该岗最强标签（组件库/大屏/IM/AI），让面试官快速给你&quot;对口&quot;定位。</li><li><strong>表达一致性？</strong> 所有岗位都复用统一叙事主线（双栈同构组件库 + 跨端 + AI 工具链），只按岗调整重点。</li></ol>',41)])])}const q=o(a,[["render",s]]);export{c as __pageData,q as default};
